// Visual physics only; gameplay dice are generated by the rules engine.
export function animateDice(rolls){if(!rolls.length)return Promise.resolve();return new Promise(resolve=>{const overlay=document.createElement('div');overlay.className='ag-dice-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','Dice results');overlay.innerHTML='<canvas></canvas><section><strong>Dice roll</strong><p aria-live="polite">Rolling…</p><button type="button">Skip animation</button></section>';document.body.append(overlay);const canvas=overlay.querySelector('canvas'),ctx=canvas.getContext('2d'),button=overlay.querySelector('button'),label=overlay.querySelector('p');overlay.querySelector('strong').textContent=rolls[0].label||'Dice roll';let w,h,raf,done=false,closed=false;const dice=rolls.map((r,i)=>({...r,x:0,y:0,vx:22+Math.random()*18,vy:-20-Math.random()*18,angle:0,spin:.15+Math.random()*.3}));function resize(){w=canvas.clientWidth;h=Math.max(80,canvas.clientHeight-overlay.querySelector("section").offsetHeight-24);const scale=Math.min(devicePixelRatio||1,2);canvas.width=w*scale;canvas.height=h*scale;ctx?.setTransform(scale,0,0,scale,0,0);}resize();const radius=Math.max(12,Math.min(38,w/10,h/8,w/(Math.min(dice.length,8)*2.3)));dice.forEach((d,i)=>{d.x=radius+(i%5)*radius*2;d.y=h-radius-Math.floor(i/5)*radius*2;});function draw(){if(!ctx)return;ctx.clearRect(0,0,w,h);for(const d of dice){ctx.save();ctx.translate(d.x,d.y);ctx.rotate(d.angle);const n=d.sides===6?4:d.sides===4?3:6;ctx.beginPath();for(let i=0;i<n;i++){const a=i*2*Math.PI/n-Math.PI/2+(n===4?Math.PI/4:0);ctx.lineTo(Math.cos(a)*radius,Math.sin(a)*radius);}ctx.closePath();ctx.fillStyle='#493b25';ctx.strokeStyle='#d4af68';ctx.lineWidth=2;ctx.fill();ctx.stroke();if(n===6){ctx.beginPath();ctx.moveTo(0,-radius);ctx.lineTo(-radius*.58,radius*.45);ctx.lineTo(radius*.58,radius*.45);ctx.closePath();ctx.stroke();}ctx.rotate(-d.angle);ctx.fillStyle='#f4e2b6';ctx.font=`bold ${radius*.85}px Georgia`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(done?d.value:d.face||d.sides,0,0);ctx.restore();}}function finish(){if(done)return;done=true;cancelAnimationFrame(raf);dice.forEach(d=>{d.angle=0;d.x=Math.max(radius,Math.min(w-radius,d.x));d.y=Math.max(radius,Math.min(h-radius,d.y));});draw();label.textContent=rolls.map(r=>`d${r.sides}: ${r.value}`).join(' · ');button.textContent='Continue';button.focus();}function close(){if(closed)return;closed=true;cancelAnimationFrame(raf);overlay.remove();resolve();}button.onclick=()=>done?close():finish();button.focus();const start=performance.now();let last=start;function tick(t){const dt=Math.min(2,(t-last)/16.67);last=t;for(const d of dice){d.x+=d.vx*dt;d.y+=d.vy*dt;d.angle+=d.spin*dt;d.spin*=Math.pow(.97,dt);d.vx*=Math.pow(.965,dt);d.vy*=Math.pow(.965,dt);if(d.x<radius||d.x>w-radius){d.x=Math.max(radius,Math.min(w-radius,d.x));d.vx*=-.85;}if(d.y<radius||d.y>h-radius){d.y=Math.max(radius,Math.min(h-radius,d.y));d.vy*=-.85;}d.face=1+Math.floor(Math.random()*d.sides);}for(let i=0;i<dice.length;i++)for(let j=i+1;j<dice.length;j++){const a=dice[i],b=dice[j],x=b.x-a.x,y=b.y-a.y,l=Math.hypot(x,y)||.01;if(l<2*radius){const nx=x/l,ny=y/l,k=(2*radius-l)/2;a.x-=nx*k;a.y-=ny*k;b.x+=nx*k;b.y+=ny*k;const v=(a.vx-b.vx)*nx+(a.vy-b.vy)*ny;if(v>0){a.vx-=v*nx;a.vy-=v*ny;b.vx+=v*nx;b.vy+=v*ny;}}}draw();if(t-start>2200)finish();else raf=requestAnimationFrame(tick);}if(!ctx||matchMedia('(prefers-reduced-motion: reduce)').matches)finish();else raf=requestAnimationFrame(tick);});}
